<?php
namespace Ishep\Validation;use DomainException;use finfo;
final class DocumentUploadValidator
{public function __construct(private array $config){}public function validate(array $file,bool $http=true):array{$error=(int)($file['error']??UPLOAD_ERR_NO_FILE);if($error!==UPLOAD_ERR_OK)throw new DomainException(in_array($error,[UPLOAD_ERR_INI_SIZE,UPLOAD_ERR_FORM_SIZE],true)?'The file exceeds the upload limit.':'The upload did not complete successfully.');$tmp=(string)($file['tmp_name']??'');if($http&&!is_uploaded_file($tmp))throw new DomainException('The upload is not a valid HTTP file upload.');if(!is_file($tmp))throw new DomainException('The uploaded file is missing.');$size=(int)filesize($tmp);if($size<1)throw new DomainException('Empty files are not allowed.');if($size>$this->config['max_bytes'])throw new DomainException('The file exceeds the 5 MB limit.');$original=basename(str_replace('\\','/',(string)($file['name']??'document')));if(substr_count($original,'.')!==1)throw new DomainException('Use a single valid file extension.');$extension=strtolower(pathinfo($original,PATHINFO_EXTENSION));$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp)?:'application/octet-stream';if(!isset($this->config['allowed'][$extension])||!in_array($mime,$this->config['allowed'][$extension],true))throw new DomainException('The detected file type does not match an allowed PDF, JPEG or PNG extension.');$safe=preg_replace('/[^A-Za-z0-9._ -]/','_',pathinfo($original,PATHINFO_FILENAME)).'.'.$extension;return['tmp'=>$tmp,'original'=>substr($safe,0,255),'extension'=>$extension,'mime'=>$mime,'size'=>$size,'sha256'=>hash_file('sha256',$tmp)];}}
